struct Case{int v,n,size,mode;std::vector<float>M;std::vector<unsigned char>g,f,ra,rc,rt;float*m;unsigned char *gd,*fd,*a,*c;bool*t;};
static const float jitter[97]={0.656619,0.891183,0.488144,0.992646,0.373326,0.531378,0.181316,0.501944,0.422195,0.660427,0.673653,0.95733,0.191866,0.111216,0.565054,0.969166,0.0237439,0.870216,0.0268766,0.519529,0.192291,0.715689,0.250673,0.933865,0.137189,0.521622,0.895202,0.942387,0.335083,0.437364,0.471156,0.14931,0.135864,0.532498,0.725789,0.398703,0.358419,0.285279,0.868635,0.626413,0.241172,0.978082,0.640501,0.229849,0.681335,0.665823,0.134718,0.0224933,0.262199,0.116515,0.0693182,0.85293,0.180331,0.0324186,0.733926,0.536517,0.27603,0.368458,0.0128863,0.889206,0.866021,0.254247,0.569481,0.159265,0.594364,0.3311,0.658613,0.863634,0.567623,0.980481,0.791832,0.152594,0.833027,0.191863,0.638987,0.669,0.772088,0.379818,0.441585,0.48306,0.608106,0.175996,0.00202556,0.790224,0.513609,0.213229,0.10345,0.157337,0.407515,0.407757,0.0526927,0.941815,0.149972,0.384374,0.311059,0.168534,0.896648};
struct Interval{int lo,hi;double exact;};
Interval witness(const std::vector<unsigned char>&f,int v,float x,float y,float z){int ix=floorf(x),iy=floorf(y),iz=floorf(z);double dx=double(x)-ix,dy=double(y)-iy,dz=double(z)-iz,sum=0;for(int oz=0;oz<2;oz++)for(int oy=0;oy<2;oy++)for(int ox=0;ox<2;ox++)sum+=f[ix+ox-1+v*(iy+oy-1+v*(iz+oz-1))]*(ox?dx:1-dx)*(oy?dy:1-dy)*(oz?dz:1-dz);double u=ldexp(1.,-24),bound=8*u/(1-8*u)*250.5+32*2.220446049250313e-16*251;return{int(floor(sum-bound+.5)),int(floor(sum+bound+.5)),sum};}
bool independent(const Case&c,const std::vector<unsigned char>&a,const std::vector<unsigned char>&b,const std::vector<unsigned char>&t){for(int i=0;i<c.n;i++){float rx=i%(c.v-2)+1.f+jitter[i%97],ry=(i/(c.v-2))%(c.v-2)+1.f+jitter[i%97],rz=floorf(float(i)/(c.v-2))/(c.v-2)+1.f+jitter[i%97],xp=rx+c.M[12],yp=ry+c.M[13],zp=rz+c.M[14];bool valid=xp>=1&&xp<c.v&&yp>=1&&yp<c.v&&zp>=1&&zp<c.v;if(t[i]!=valid)return false;if(!valid){if(a[i]||b[i])return false;continue;}auto f=witness(c.f,c.v,xp,yp,zp),g=witness(c.g,c.v,rx,ry,rz);if(a[i]<f.lo||a[i]>f.hi||b[i]<g.lo||b[i]>g.hi)return false;}return true;}
int main(){std::vector<Case>cases;std::vector<float>prefix;for(int v:{17,33})for(int mode:{0,1}){Case c;c.v=v;c.mode=mode;c.n=v*v*v;c.size=(v+1)*(v+1)*(v+5);c.M.assign(16,0);c.M[0]=c.M[5]=c.M[10]=c.M[15]=1;if(mode){c.M[12]=.25f;c.M[13]=.5f;c.M[14]=.125f;}c.g.resize(c.size);c.f.resize(c.size);for(int i=0;i<c.size;i++){c.g[i]=(i*17+i/v*7)%251;c.f[i]=(i*29+i/(v*v)*13)%251;}c.ra.resize(c.n);c.rc.resize(c.n);c.rt.resize(c.n);bool*ref=new bool[c.n];spm_reference(c.M.data(),c.n,c.g.data(),c.f.data(),make_int3(v,v,v),make_int3(v,v,v),c.ra.data(),c.rc.data(),ref);for(int i=0;i<c.n;i++)c.rt[i]=ref[i];delete[]ref;cudaMalloc(&c.m,64);cudaMalloc(&c.gd,c.size);cudaMalloc(&c.fd,c.size);cudaMalloc(&c.a,c.n);cudaMalloc(&c.c,c.n);cudaMalloc(&c.t,c.n);cudaMemcpy(c.m,c.M.data(),64,cudaMemcpyHostToDevice);cudaMemcpy(c.gd,c.g.data(),c.size,cudaMemcpyHostToDevice);cudaMemcpy(c.fd,c.f.data(),c.size,cudaMemcpyHostToDevice);for(int x:{v,mode,c.n,c.size,3})prefix.push_back(x);prefix.insert(prefix.end(),c.M.begin(),c.M.end());for(auto x:c.g)prefix.push_back(x);for(auto x:c.f)prefix.push_back(x);cases.push_back(c);}
auto run=[&](Case&c,std::vector<float>&out){cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int rep=0;rep<3;rep++)spm<<<256,128>>>(c.m,c.n,c.gd,c.fd,make_int3(c.v,c.v,c.v),make_int3(c.v,c.v,c.v),c.a,c.c,c.t);cudaDeviceSynchronize();double time=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/3;std::vector<unsigned char>a(c.n),b(c.n),t(c.n);cudaMemcpy(a.data(),c.a,c.n,cudaMemcpyDeviceToHost);cudaMemcpy(b.data(),c.c,c.n,cudaMemcpyDeviceToHost);cudaMemcpy(t.data(),c.t,c.n,cudaMemcpyDeviceToHost);int err=0;bool ok=cudaGetLastError()==cudaSuccess;for(int i=0;i<c.n;i++){err=std::max(err,abs(int(a[i])-int(c.ra[i])));err=std::max(err,abs(int(b[i])-int(c.rc[i])));ok&=t[i]==c.rt[i];}for(auto x:a)out.push_back(x);for(auto x:b)out.push_back(x);for(auto x:t)out.push_back(x);return std::make_tuple(time,ok&&independent(c,a,b,t),err);};std::vector<float>tmp;for(auto&c:cases)run(c,tmp);for(int trial=1;trial<=5;trial++){auto out=prefix;double time=0;bool ok=true;int err=0;std::cout<<"STUDY_COMPONENT_SECONDS ";for(auto&c:cases){auto[t,pass,e]=run(c,out);time+=t;ok&=pass;err=std::max(err,e);std::cout<<std::setprecision(17)<<t<<",";}std::cout<<std::endl;std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();std::cout<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<time<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<out.size()<<",\"max_abs_error\":"<<err<<",\"timing_region\":\"sum4_three_spm_kernel_means\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\""<<path<<"\",\"dtype\":\"float32\",\"count\":"<<out.size()<<",\"byte_order\":\"little\"}}"<<std::endl;if(!ok)return 2;}}
